package br.ufla.agendainteligente.servico;
import br.ufla.agendainteligente.dominio.*; import br.ufla.agendainteligente.dto.Dtos.*; import br.ufla.agendainteligente.erro.ExcecaoRegraNegocio; import br.ufla.agendainteligente.repositorio.*; import java.time.*; import java.util.*; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service
public class ServicoAgenda {
 private static final ZoneId FUSO = ZoneId.of("America/Sao_Paulo"); private static final int INTERVALO_MINUTOS=30;
 private final RepositorioProfissional profissionais; private final RepositorioServico servicos; private final RepositorioDisponibilidade disponibilidades; private final RepositorioAgendamento agendamentos;
 public ServicoAgenda(RepositorioProfissional profissionais, RepositorioServico servicos, RepositorioDisponibilidade disponibilidades, RepositorioAgendamento agendamentos){this.profissionais=profissionais;this.servicos=servicos;this.disponibilidades=disponibilidades;this.agendamentos=agendamentos;}
 public Profissional profissional(String slug){return profissionais.findBySlug(slug).orElseThrow(()->new NoSuchElementException("Profissional nao encontrado"));}
 public List<ServicoResposta> listarServicos(Profissional profissional){return servicos.findByProfissionalIdAndAtivoTrueOrderByNome(profissional.getId()).stream().map(s->new ServicoResposta(s.getId(),s.getNome(),s.getDuracaoMinutos())).toList();}
 public List<DisponibilidadeResposta> listarDisponibilidades(Profissional profissional){return disponibilidades.findByProfissionalIdOrderByDiaSemanaAscHoraInicioAsc(profissional.getId()).stream().map(d->new DisponibilidadeResposta(d.getId(),d.getDiaSemana(),d.getHoraInicio(),d.getHoraFim())).toList();}
 @Transactional public ServicoResposta criarServico(Profissional profissional, CriarServicoPedido pedido){Servico servico=new Servico();servico.criar(profissional,pedido.nome().trim(),pedido.duracaoMinutos());servicos.save(servico);return new ServicoResposta(servico.getId(),servico.getNome(),servico.getDuracaoMinutos());}
 @Transactional public void desativarServico(Profissional profissional, Long id){Servico servico=servicos.findByIdAndProfissionalId(id,profissional.getId()).orElseThrow(()->new NoSuchElementException("Servico nao encontrado"));servico.desativar();}
 @Transactional public DisponibilidadeResposta criarDisponibilidade(Profissional profissional, CriarDisponibilidadePedido pedido){if(!pedido.horaFim().isAfter(pedido.horaInicio()))throw new ExcecaoRegraNegocio("O horario final deve ser posterior ao inicial.");Disponibilidade d=new Disponibilidade();d.criar(profissional,pedido.diaSemana(),pedido.horaInicio(),pedido.horaFim());disponibilidades.save(d);return new DisponibilidadeResposta(d.getId(),d.getDiaSemana(),d.getHoraInicio(),d.getHoraFim());}
 @Transactional public void excluirDisponibilidade(Profissional profissional, Long id){Disponibilidade d=disponibilidades.findById(id).orElseThrow(()->new NoSuchElementException("Disponibilidade nao encontrada"));disponibilidades.delete(d);}
 public List<LocalTime> horariosLivres(Profissional profissional, Long servicoId, LocalDate data){Servico servico=servicos.findByIdAndProfissionalId(servicoId,profissional.getId()).filter(Servico::isAtivo).orElseThrow(()->new NoSuchElementException("Servico nao encontrado"));int dia=data.getDayOfWeek().getValue();List<LocalTime> horarios=new ArrayList<>();for(Disponibilidade disponibilidade:disponibilidades.findByProfissionalIdAndDiaSemanaOrderByHoraInicioAsc(profissional.getId(),dia)){for(LocalTime atual=disponibilidade.getHoraInicio();!atual.plusMinutes(servico.getDuracaoMinutos()).isAfter(disponibilidade.getHoraFim());atual=atual.plusMinutes(INTERVALO_MINUTOS)){OffsetDateTime inicio=converter(data,atual),fim=inicio.plusMinutes(servico.getDuracaoMinutos());if(agendamentos.buscarSobrepostos(profissional.getId(),inicio,fim).isEmpty())horarios.add(atual);}}return horarios;}
 @Transactional public AgendamentoResposta criarAgendamento(Profissional profissional, CriarAgendamentoPedido pedido){Servico servico=servicos.findByIdAndProfissionalId(pedido.servicoId(),profissional.getId()).filter(Servico::isAtivo).orElseThrow(()->new NoSuchElementException("Servico nao encontrado"));OffsetDateTime inicio=converter(pedido.data(),pedido.horario()),fim=inicio.plusMinutes(servico.getDuracaoMinutos());boolean dentroDaDisponibilidade=disponibilidades.findByProfissionalIdAndDiaSemanaOrderByHoraInicioAsc(profissional.getId(),pedido.data().getDayOfWeek().getValue()).stream().anyMatch(d->!pedido.horario().isBefore(d.getHoraInicio())&&!pedido.horario().plusMinutes(servico.getDuracaoMinutos()).isAfter(d.getHoraFim()));if(!dentroDaDisponibilidade)throw new ExcecaoRegraNegocio("O horario escolhido nao esta disponivel.");if(!agendamentos.buscarSobrepostos(profissional.getId(),inicio,fim).isEmpty())throw new ExcecaoRegraNegocio("Este horario acabou de ser reservado. Escolha outro horario.");Agendamento agendamento=new Agendamento();agendamento.criar(profissional,servico,pedido.nomeCliente().trim(),pedido.contatoCliente().trim(),inicio,fim);try{agendamentos.saveAndFlush(agendamento);}catch(DataIntegrityViolationException erro){throw new ExcecaoRegraNegocio("Este horario acabou de ser reservado. Escolha outro horario.");}return resposta(agendamento);}
 public List<AgendamentoResposta> agenda(Profissional profissional, LocalDate data){OffsetDateTime inicio=converter(data,LocalTime.MIN),fim=converter(data.plusDays(1),LocalTime.MIN);return agendamentos.buscarPorPeriodo(profissional.getId(),inicio,fim).stream().map(this::resposta).toList();}
 private OffsetDateTime converter(LocalDate data,LocalTime hora){return ZonedDateTime.of(data,hora,FUSO).toOffsetDateTime();} private AgendamentoResposta resposta(Agendamento a){return new AgendamentoResposta(a.getId(),a.getServico().getNome(),a.getNomeCliente(),a.getContatoCliente(),a.getInicio(),a.getFim());}
}
